{
  "candidate_edge_types": [
    {
      "name": "INVESTIGATES_ROOT_CAUSE_OF_ANOMALOUS_RESULT",
      "definition": "After observing an execution result with an unexpected or anomalous outcome, the agent performs a diagnostic action that inspects source code or system state to determine the underlying cause of the anomaly.",
      "source_description": "An earlier execution result whose outcome is unexpected or anomalous (e.g., an abnormal exit status despite apparently successful output).",
      "target_description": "A diagnostic action that examines source code or system state in order to explain the anomalous result."
    },
    {
      "name": "CREATES_ADAPTED_ARTIFACT_FOR_INCOMPATIBLE_RESOURCE",
      "definition": "After inspecting an existing resource and determining that it is incompatible, outdated, or unsuitable for the current environment, the agent authors a modified or replacement artifact tailored to that environment.",
      "source_description": "An inspected existing resource (e.g., configuration or machine-specific source) identified as incompatible or outdated for the current environment.",
      "target_description": "An agent action that authors a modified or replacement artifact adapted to the current environment."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR_DIAGNOSED_DEFECT",
      "definition": "Following the identification of the cause of a defect or unwanted behavior, the agent modifies a configuration or source artifact and rebuilds in order to correct that defect.",
      "source_description": "A diagnosed cause of a defect or unwanted behavior in the produced program.",
      "target_description": "An action that modifies a configuration or source artifact and rebuilds to correct the diagnosed defect."
    },
    {
      "name": "VERIFIES_REPAIR_BY_REPEATING_CHECK",
      "definition": "After applying a repair to an artifact, the agent re-executes the same check that previously produced the unfavorable outcome in order to confirm that the repair succeeded.",
      "source_description": "A previously diagnosed and repaired execution outcome that had produced an unfavorable result.",
      "target_description": "A re-execution of the earlier check performed to confirm that the repair resolved the problem."
    },
    {
      "name": "VALIDATES_PRODUCED_OUTPUT_ARTIFACT",
      "definition": "The agent performs an additional verification action that inspects an artifact produced by earlier execution to confirm that it exists and has the expected properties (such as expected size or format).",
      "source_description": "An artifact produced by an earlier execution step whose properties need confirmation.",
      "target_description": "A verification action that inspects the produced artifact to confirm it has the expected properties."
    },
    {
      "name": "USES_PRIOR_EXECUTION_OUTPUT_AS_INPUT",
      "definition": "A subsequent agent action consumes an artifact or value produced by an earlier execution step, using it as an input, operand, or argument for that action.",
      "source_description": "An artifact or value produced as output by an earlier execution step.",
      "target_description": "A subsequent action that uses that earlier output as an input, operand, or argument."
    }
  ]
}

